INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('dfffa1d2-75cf-47f4-9e04-af41102c3149','9','geografie-fizica','published',0,61,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('dfffa1d2-75cf-47f4-9e04-af41102c3149','ro','De ce ni se pare că Soarele răsare la est și apune la vest, deși el nu se rotește în jurul nostru?','["Pentru că Pământul se rotește în jurul axei sale de la vest spre est, iar noi ne mișcăm odată cu el.","Pentru că Soarele se rotește în jurul Pământului de la est spre vest.","Pentru că Pământul face o revoluție completă în jurul Soarelui într-o singură zi.","Pentru că axa Pământului își schimbă înclinarea în fiecare zi."]','Gândește-te cine se mișcă de fapt: noi sau Soarele. Fiindcă Pământul se rotește spre est, peisajul (și noi) ne îndreptăm spre Soare dimineața, așa că el pare că răsare la est.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('c90a8907-a2b4-4a19-b339-e7454ba2466a','9','geografie-fizica','published',1,62,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('c90a8907-a2b4-4a19-b339-e7454ba2466a','ro','Un punct de la Ecuator și unul de lângă polul Nord fac fiecare o rotație completă în 24 de ore. De ce are totuși punctul de la Ecuator o viteză liniară mult mai mare?','["Pentru că la Ecuator ziua durează mai mult de 24 de ore.","Pentru că parcurge un cerc mult mai mare în același interval de timp.","Pentru că la Ecuator gravitația este mai mare.","Pentru că punctul de lângă pol se rotește în sens invers."]','Amândouă au același timp la dispoziție (24 h), deci compară lungimea drumului. Punctul de la Ecuator descrie cel mai mare cerc de pe glob, așa că trebuie să meargă mult mai repede pentru a-l parcurge în aceleași 24 de ore.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f31afb00-3352-4a07-8063-6be3a229533a','9','geografie-fizica','published',2,63,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f31afb00-3352-4a07-8063-6be3a229533a','ro','Turtirea Pământului la poli și bombarea lui la Ecuator sunt puse pe seama mișcării de rotație. Care este mecanismul?','["Atracția Lunii trage materia spre Ecuator.","Revoluția în jurul Soarelui întinde planeta.","Rotația produce o forță centrifugă, maximă la Ecuator, care bombează planeta acolo.","Înclinarea axei apasă asupra polilor."]','Leagă forma de faptul că planeta se învârte. Rotația generează o forță centrifugă cu atât mai mare cu cât ești mai departe de axă — deci maximă la Ecuator, unde bombează planeta, și nulă la poli.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('dda053d4-aa32-4d88-bed3-e9642231c873','9','geografie-fizica','published',3,64,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('dda053d4-aa32-4d88-bed3-e9642231c873','ro','Un vânt care bate dinspre nord spre sud în emisfera nordică nu urmează o linie dreaptă, ci pare abătut. În ce direcție, din cauza efectului Coriolis?','["Rămâne exact pe direcția inițială.","Spre stânga.","Direct în sus, spre atmosfera înaltă.","Spre dreapta."]','Reține regula: în emisfera nordică, devierea este spre dreapta. Orice corp aflat în mișcare liberă (vânt, curent, apă) este abătut spre dreapta în emisfera nordică, tocmai pentru că Pământul se rotește sub el.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('776dce43-2818-483e-8658-fe7b9d523686','9','geografie-fizica','published',1,65,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('776dce43-2818-483e-8658-fe7b9d523686','ro','Efectul Coriolis nu este la fel de puternic peste tot. Unde este el cel mai slab (practic nul)?','["La cei doi poli.","La Ecuator.","La tropice.","La cercurile polare."]','Efectul crește dinspre Ecuator spre poli, deci caută capătul opus polilor. La Ecuator devierea Coriolis este practic nulă, motiv pentru care acolo marile bucle ale vânturilor și curenților aproape că nu apar.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('66b23192-3401-417c-bc51-c3c38a346f01','9','geografie-fizica','published',0,66,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('66b23192-3401-417c-bc51-c3c38a346f01','ro','De ce un fus orar acoperă tocmai 15° de longitudine?','["Pentru că cele 360° ale globului împărțite la cele 24 de ore ale zilei dau 15° pentru fiecare oră.","Pentru că Pământul are 15 mari continente.","Pentru că ziua are în medie 15 ore de lumină.","Pentru că un grad de longitudine măsoară 15 km."]','Împarte întreg globul (360°) la numărul de ore dintr-o zi. 360° ÷ 24 h = 15° pe oră, deci fiecărei ore îi corespunde o fâșie de 15° longitudine — un fus orar.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('6a7991f8-41e9-40e4-b7f9-dd4708e2c5ac','9','geografie-fizica','published',2,67,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('6a7991f8-41e9-40e4-b7f9-dd4708e2c5ac','ro','Un călător pleacă de la meridianul Greenwich și se deplasează spre est, traversând 3 fuse orare. Ce trebuie să facă cu ceasul?','["Să scadă 3 ore.","Să lase ceasul neschimbat.","Să adauge 3 ore.","Să adauge 15 ore."]','Amintește-ți regula: spre est se adaugă, spre vest se scade. Mergând spre est, în sensul rotației, ora „o ia înainte”, așa că adăugăm câte o oră pentru fiecare fus traversat — 3 fuse înseamnă +3 ore.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f5a0ce99-90fc-4298-b947-8b1c2d94d793','9','geografie-fizica','published',1,68,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f5a0ce99-90fc-4298-b947-8b1c2d94d793','ro','O navă traversează linia de schimbare a datei (meridianul de 180°) mergând spre vest. Ce se întâmplă cu data calendaristică?','["Rămâne aceeași zi.","Se trece direct în ziua următoare.","Se dă înapoi cu două zile.","Se schimbă doar anul, nu și ziua."]','Leagă sensul traversării de regula datei: spre vest se sare o zi înainte. Trecând linia de 180° spre vest, calendarul avansează cu o zi, așa că nava intră direct în ziua următoare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('a78b01f8-66a1-4fc0-9f04-a5ce51e8aec6','9','geografie-fizica','published',3,69,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('a78b01f8-66a1-4fc0-9f04-a5ce51e8aec6','ro','La fiecare 4 ani introducem un an bisect, cu 366 de zile (o zi în plus, 29 februarie). De ce este nevoie de această corecție?','["Pentru că Pământul se rotește mai încet o dată la 4 ani.","Pentru că orbita devine mai lungă la fiecare 4 ani.","Pentru că axa își schimbă înclinarea la 4 ani.","Pentru că anul durează de fapt circa 365 de zile și 6 ore, iar cele 6 ore neluate în seamă se adună într-o zi întreagă la 4 ani."]','Observă că o revoluție nu are fix 365 de zile rotunde. Cele aproximativ 6 ore care „prisosesc” anual se adună: 4 × 6 h = 24 h = o zi, pe care o adăugăm o dată la 4 ani, ca să nu rămână calendarul în urmă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('10aae763-d99f-4f2a-87dd-b5de3a075840','9','geografie-fizica','published',0,70,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('10aae763-d99f-4f2a-87dd-b5de3a075840','ro','Pământul este cel mai aproape de Soare în ianuarie, totuși în emisfera nordică atunci este iarnă. Ce dovedește acest fapt?','["Că anotimpurile nu sunt date de distanța până la Soare, ci de înclinarea constantă a axei.","Că ianuarie ar trebui să fie, de fapt, cea mai caldă lună.","Că Pământul se oprește din rotație în timpul iernii.","Că emisfera sudică nu are deloc anotimpuri."]','Dacă distanța ar decide, cea mai apropiată lună ar fi cea mai caldă peste tot — dar nu este așa. Anotimpurile depind de unghiul sub care fiecare emisferă primește razele, adică de înclinarea axei, nu de distanța Pământ–Soare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('c3492cc7-4539-49a6-9bcc-95296380244f','9','geografie-fizica','published',1,71,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('c3492cc7-4539-49a6-9bcc-95296380244f','ro','Imaginează-ți că axa Pământului ar fi perfect dreaptă (neînclinată), dar planeta ar continua să se rotească și să facă revoluția. Ce s-ar întâmpla cel mai probabil?','["Zilele ar deveni mai lungi de 24 de ore.","Nu ar mai exista succesiunea anotimpurilor, pentru că emisferele ar primi mereu razele la fel.","Pământul nu s-ar mai roti în jurul axei.","Soarele ar începe să răsară la vest."]','Anotimpurile vin din faptul că axa înclinată orientează pe rând emisferele spre Soare — deci înlătură înclinarea și vezi ce dispare. Fără înclinare, fiecare emisferă ar primi mereu aceleași raze, iar anotimpurile nu ar mai exista.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('fcc9e844-605f-49e8-9c6d-92965ba0db38','9','geografie-fizica','published',2,72,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('fcc9e844-605f-49e8-9c6d-92965ba0db38','ro','La echinocții, ziua este egală cu noaptea pe întreaga planetă. Care este explicația?','["Pentru că Pământul se oprește pe orbită în acele zile.","Pentru că atunci Pământul este cel mai aproape de Soare.","Pentru că cercul de iluminare trece prin cei doi poli și taie fiecare paralelă în două jumătăți egale.","Pentru că axa devine dreaptă doar în zilele de echinocțiu."]','Gândește-te cum trebuie să cadă linia dintre lumină și întuneric ca fiecare loc să stea la fel de mult la soare și la umbră. La echinocții cercul de iluminare trece exact prin poli, împărțind orice paralelă în două părți egale — de aici 12 h zi și 12 h noapte peste tot.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('23af86e9-8a0e-444e-9398-4f8857608207','9','geografie-fizica','published',0,73,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('23af86e9-8a0e-444e-9398-4f8857608207','ro','La solstițiul de vară (22 iunie, pentru emisfera nordică), unde ajunge Soarele la zenit (exact deasupra capului) la amiază?','["Pe Tropicul Racului, la 23°27′ latitudine nordică.","Pe Ecuator.","Deasupra polului Nord.","Pe Tropicul Capricornului, în emisfera sudică."]','La solstiții Soarele bate perpendicular pe unul dintre tropice, iar vara emisferei nordice îl duce spre nord. La 22 iunie razele cad perpendicular pe Tropicul Racului (23°27′ N), limita nordică până la care Soarele mai ajunge la zenit.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e9e38d5c-71b9-4e08-9d1a-fcf82e6681b1','9','geografie-fizica','published',3,74,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e9e38d5c-71b9-4e08-9d1a-fcf82e6681b1','ro','La solstițiul de vară pentru emisfera nordică, ce se petrece dincolo de Cercul polar de Nord?','["Este noapte tot timpul (noapte polară).","Ziua este exact egală cu noaptea.","Soarele ajunge la zenit, exact deasupra capului.","Este zi polară: Soarele nu apune sub orizont."]','Vara emisferei nordice înseamnă că polul Nord este înclinat spre Soare — gândește-te dacă acolo se mai face întuneric. Fiind orientat spre Soare, ținutul de dincolo de Cercul polar de Nord rămâne luminat non-stop: Soarele nu apune, deci este zi polară.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('5af1c855-02f2-484f-a1f8-bb136fc3ef60','9','geografie-fizica','published',1,75,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('5af1c855-02f2-484f-a1f8-bb136fc3ef60','ro','De ce razele solare încălzesc mai puternic atunci când Soarele este sus pe cer decât atunci când este jos, aproape de orizont?','["Pentru că sus pe cer Soarele este vizibil mai aproape de Pământ.","Pentru că razele cad aproape perpendicular și își concentrează energia pe o suprafață mică.","Pentru că razele oblice conțin, în sine, mai multă energie.","Pentru că noaptea razele solare dispar complet."]','Compară o rază verticală cu una oblică: pe ce suprafață se împrăștie fiecare? Razele aproape perpendiculare încălzesc o suprafață mică, deci energia este concentrată; razele oblice se întind pe o suprafață mai mare și încălzesc mai slab.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('d18c800a-fd3f-417b-91df-44b89727d08e','9','geografie-fizica','published',2,76,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('d18c800a-fd3f-417b-91df-44b89727d08e','ro','Când în emisfera nordică este vară, în emisfera sudică este:','["tot vară, în același timp.","primăvară.","iarnă.","niciun anotimp, pentru că sudul nu are anotimpuri."]','Cele două emisfere sunt înclinate în sensuri opuse față de Soare în același moment. Când nordul este întors spre Soare (vară), sudul este întors dinspre Soare (iarnă) — de aceea anotimpurile sunt mereu inversate între emisfere.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9226e772-4b21-4cfb-85e4-89995bfa759a','9','geografie-fizica','published',0,77,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9226e772-4b21-4cfb-85e4-89995bfa759a','ro','De ce zona caldă a Pământului se află tocmai în jurul Ecuatorului?','["Pentru că acolo razele solare cad aproape perpendicular tot timpul anului.","Pentru că Ecuatorul este partea cea mai apropiată de Soare.","Pentru că la Ecuator axa Pământului este verticală.","Pentru că Ecuatorul se rotește mai încet decât restul planetei."]','Leagă temperatura de unghiul razelor, nu de distanța până la Soare. Fiindcă la Ecuator razele cad aproape perpendicular tot anul, energia primită este maximă, iar temperaturile sunt ridicate — de aici zona caldă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e7b1546a-a71e-4fd4-8993-fc6cd2a72427','9','geografie-fizica','published',1,78,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e7b1546a-a71e-4fd4-8993-fc6cd2a72427','ro','Între ce limite se întind zonele temperate, în care se află și România?','["Între Ecuator și cele două tropice.","Între tropice și cercurile polare.","Între cercurile polare și poli.","Doar în imediata apropiere a polilor."]','Zonele temperate stau „la mijloc”, între zona caldă și zonele reci. Ele se întind între tropice (23°27′) și cercurile polare (66°33′), au cele patru anotimpuri distincte și cuprind și România.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('1bd961a9-494d-4951-9c44-31d0c8ab8b87','9','geografie-fizica','published',2,79,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('1bd961a9-494d-4951-9c44-31d0c8ab8b87','ro','Succesiunea zi-noapte și succesiunea anotimpurilor sunt fenomene diferite. Care este asocierea corectă cu mișcarea care le produce?','["Ambele sunt produse de mișcarea de revoluție.","Ziua-noaptea de revoluție, iar anotimpurile de rotație.","Ziua-noaptea de rotație, iar anotimpurile de revoluție (prin înclinarea axei).","Ambele sunt produse de mișcarea de rotație."]','Întreabă-te ce durează o zi (ceva scurt) și ce durează un an (ceva lung), apoi potrivește mișcarea. Ziua și noaptea vin din rotația de 24 h, iar anotimpurile din revoluția de un an combinată cu înclinarea axei.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('07f2286c-acc3-41bf-bc20-8b68d67f0d51','9','geografie-fizica','published',3,80,1783100000000,1783100000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('07f2286c-acc3-41bf-bc20-8b68d67f0d51','ro','Un râu mare din emisfera nordică își erodează în timp mai puternic unul dintre maluri. Care mal și de ce?','["Malul stâng, din cauza mișcării de revoluție.","Ambele maluri în mod egal, fără vreo cauză anume.","Malul stâng, din cauza forței centrifuge de la Ecuator.","Malul drept, pentru că forța Coriolis abate apa în mișcare spre dreapta în emisfera nordică."]','Aplică regula Coriolis (dreapta în emisfera nordică) la apa care curge. Fiind împinsă constant spre dreapta, apa apasă și erodează mai tare malul drept al râului în emisfera nordică.');
